        ImageVector.Builder(name,24.dp,24.dp,data.first,data.second).apply {
            addGroup(translationY=if(data.second>24f)data.second else 0f)
            data.third.forEach {addPath(PathParser().parsePathString(it).toNodes(),fill=SolidColor(Color.Black))}
            clearGroup()
        }.build()
    }
